-- ============================================================
-- ML PREDICTION
-- Predictions generated by your trained ML model.
--
-- Can eventually be compared against:
--   raw weather forecast
--   observation
-- ============================================================

CREATE TABLE ml_prediction (
    id BIGSERIAL PRIMARY KEY,

    ml_model_id BIGINT NOT NULL,
    grid_point_id BIGINT NOT NULL,

    source_forecast_id BIGINT,

    issued_at TIMESTAMPTZ NOT NULL,
    valid_at TIMESTAMPTZ NOT NULL,

    predicted_temperature_c REAL,
    predicted_precipitation_mm REAL,

    predicted_error_temperature_c REAL,

    datein TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    datemodified TIMESTAMPTZ NOT NULL DEFAULT NOW(),


    CONSTRAINT uq_ml_prediction
        UNIQUE (
            ml_model_id,
            grid_point_id,
            issued_at,
            valid_at
        )
);


CREATE INDEX idx_ml_prediction_grid_point
ON ml_prediction (grid_point_id);

CREATE INDEX idx_ml_prediction_valid_at
ON ml_prediction (valid_at);

CREATE INDEX idx_ml_prediction_model
ON ml_prediction (ml_model_id);